import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    cache = {}

    def memoized(*args, **kwargs):
        key = args + tuple(sorted(kwargs.items()))

        if key in cache:
            entry = cache[key]
            if entry['expiration'] >= timer():
                return entry['result']
            else:
                del cache[key]

        result = func(*args, **kwargs)
        cache[key] = {'expiration': timer() + ttl, 'result': result}

        if len(cache) > maxsize:
            # evict the least recently used entry
            least_recent_expiration = float('inf')
            least_recent_key = None
            for key, entry in cache.items():
                if entry['expiration'] < least_recent_expiration:
                    least_recent_expiration = entry['expiration']
                    least_recent_key = key

            del cache[least_recent_key]

        return result

    return memoized

