def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """

    class LruCache(object):
        def __init__(self, maxsize=128, typed=False):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.hits = {}
            self.misses = 0

        def __call__(self, func):
            slot = (func, cached)

            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, tuple(sorted(kwargs.items())))
                if key in self.cache:
                    res = self.cache[key]
                    self.hits[key] = res
                    return res
                else:
                    self.misses += 1
                    value = func(*args, **kwargs)
                    if len(self.cache) == self.maxsize:
                        lru_key_set = set()
                        for key in self.hits.keys():
                            if self.hits[key] == min(self.hits.values()):
                                lru_key_set.add(key)
                        lru_key = min(lru_key_set)
                        del self.cache[lru_key]
                        del self.hits[lru_key]
                    self.cache[key] = value
                    return value

            @functools.wraps(func)
            def typed_wrapper(*args, **kwargs):
                key = (args, tuple(sorted(kwargs.items())))
                if key in self.cache:
                    res = self.cache[key]
                    self.hits[key] = res
                    return res
                else:
                    self.misses += 1
                    value = func(typ=args[0] if self.typed else None, *args[1:], **kwargs)
                    if len(self.cache) == self.maxsize:
                        lru_key_set = set()
                        for key in self.hits.keys():
                            if self.hits[key] == min(self.hits.values()):
                                lru_key_set.add(key)
                        lru_key = min(lru_key_set)
                        del self.cache[lru_key]
                        del self.hits[lru_key]
                    self.cache[key] = value
                    return value

            if typed:
                return typed_wrapper
            else:
                return wrapper

    return LruCache(maxsize, typed)

