def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    if not hasattr(cachedmethod, 'cache_method'):
        class MemoizedMethod:
            def __init__(self, func):
                self.func = func
                self.cache = {}

            def __call__(self, *args, **kwargs):
                # Compute the key using the given key function
                key = hash(key(*args, **kwargs))

                # Check if the result is in the cache
                if key in self.cache:
                    return self.cache[key]

                # Mark the method as being executed
                self.cache[key] = None

                # Safe call the actual function
                result = self.func(*args, **kwargs)

                # Update the cache with the computed result
                if result is not None:
                    self.cache[key] = result

                return result

        cachedmethod.cache_method = MemoizedMethod
    return cachedmethod.cache_method

