def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not isinstance(sequence, list):
        raise TypeError("Input 'sequence' must be a list.")

    normalized_args = []

    for arg in sequence:
        if isinstance(arg, (Declaration, tuple)):
            if output is not None:
                output.append(arg)
                return normalized_args
            normalized_args.extend(arg)
        elif isinstance(arg, Interface) or isinstance(arg, implements_specs):
            if arg in normalized_args:
                raise ValueError("Duplicate interface or specification.")
            normalized_args.append(arg)
        else:
            # Expand interfaces and implements specs
            normalized_args.extend(arg.declarations(), arg.implements())

    if output is not None:
        output.extend(normalized_args)

    return normalized_args

