def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if "error" not in context:
        context.error = {}

    error_indices = []
    for field in ["E", "t", "error_E_low"]:
        if field in self.context:
            if field == "E":
                error_indices.append(self.context.field_indexE)
            elif field == "t":
                error_indices.append(self.context.field_indext)
            elif field == "error_E_low":
                error_indices.append(self.context.field_indexerror_E_low)
            self.context.value[field] = self.__getattr__(field).tolist()
            for error in self.__getattr__(field):
                error_indices.append(sum(error.ID * self.context.field_denominator(field)))
            del(self.__getattr__(field))
        elif field in context.error:
            context.error[field].update(self.context.error[field].items())
        else:
            context.error[field] = {}

    context.error.update({field: error_indices for field in ["x", "y", "z"] if field in self.context})
    context.error.update({"location": self.context.location})
    context.error.update({"time": self.context.time})

