    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

            A & (A | B) = A, A | (A & B) = A

    Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for i, arg in enumerate(args):
        if isinstance(arg, (x or y or z)) and isinstance(arg.arg, (x or y or z)):
            # Apply absorption
            if arg.arg.class_name == arg.class_name:
                if arg.arg.arg == arg.arg:
                    result.append(arg)
                else:
                    result.append(arg.arg)
            # Apply negative absorption
            elif arg.arg.class_name == arg.class_name:
                if arg.arg.arg != arg.arg:
                    result.append(arg)
            elif arg.arg.class_name == ~arg.class_name:
                if arg.arg.arg == arg.arg:
                    result.append(arg)
                else:
                    result.append(arg.arg)
            else:
                result.append(arg)
        else:
