def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] == 2:  # Python 2
        # Define a wrapper function that converts the unicode string to bytes
        def tzname_in_bytes_to_unicode(string):
            return string.encode('utf-8')

    elif sys.version_info[0] == 3:  # Python 3
        # Define a wrapper function that converts the byte string to unicode
        def tzname_in_bytes_to_unicode(string):
            return string.decode('utf-8')

    return tzname_in_bytes_to_unicode

