    """
    Verify that the *candidate* might correctly provide *iface*.

    Returns True if the candidate's __class__ is directly compatible with iface, False otherwise.

    (The idea is to ensure that the candidates were indeed instantiated from the iface and that
     their type is compatible with the one exposed by this Tracy object.)
    """
    if tentative:
        if type(candidate) == iface:
            return True
        return False
    else:
        # Check if the candidate is an instance of iface
        if not isinstance(candidate, iface):
            return False
        # Iterate through the methods in iface and check that all required ones are implemented by the candidate
        for method in iface.__mro__:
            if not hasattr(candidate, method.__name__):
                return False
        return True

