def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is provided, return it
    if explicit_mc is not None:
        return explicit_mc

    # Find the metaclass implied by multiple inheritance
    metaclses = [base.__metaclass__ for base in bases if hasattr(base, '__metaclass__')]
    if metaclses:
        metacls = metaclses[0]
    else:
        metacls = MetaClass

    return metacls

