public class ElementUtils {

    public static void xml_children_as_dict(Element node) {
        // Assuming the input node is a Document or an Element
        if (node.getNodeType() == Node.DOCUMENT_NODE) {
            Document doc = (Document) node;
            NodeList nodeList = doc.getDocumentElement().getChildNodes();
            for (int i = 0; i < nodeList.getLength(); i++) {
                Element childNode = (Element) nodeList.item(i);
                String tagName = childNode.getNodeName();
                ElementUtils.xml_children_as_dict(childNode);
            }
        } else if (node.getNodeType() == Node.ELEMENT_NODE) {
            // Handle the case where node is an Element
            String tagName = node.getNodeName();
            // Add the tag name and its attributes to the dictionary
            Map<String, String> attributes = new HashMap<>();
            for (Node attributeNode : node.attributes()) {
                String attributeName = attributeNode.getNodeName();
                String attributeValue = attributeNode.getNodeValue();
                attributes.put(attributeName, attributeValue);
            }
            // Optionally, add the tag name and attributes to the dictionary
            elementMap.put(tagName, attributes);
        }
    }

    private static Map<String, Map<String, String>> elementMap = new HashMap<>();

}

