def strip_root(path, root):
    """Remove root from path, throw exception on failure."""

    try:
        # Check if the root is present in the path
        if root in path:
            # Extend path without the root and raise an exception if the result is empty
            path.pop(0)
            if not path:
                raise ValueError("The path is empty after stripping the root.")
        else:
            raise ValueError(f"The specified root '{root}' is not present in the path.")
    except Exception as e:
        raise ValueError(str(e), path)

